def mean(numbers):
    """Return the arithmetic mean of a sequence of numbers.

    Raises:
        ValueError: If the sequence is empty.
    """
    if not numbers:
        raise ValueError("Cannot compute mean of an empty sequence.")
    return sum(numbers) / len(numbers)


def median(numbers):
    """Return the median of a sequence of numbers.

    Supports both odd and even length sequences.

    Raises:
        ValueError: If the sequence is empty.
    """
    if not numbers:
        raise ValueError("Cannot compute median of an empty sequence.")
    sorted_nums = sorted(numbers)
    n = len(sorted_nums)
    mid = n // 2
    if n % 2 == 1:
        return sorted_nums[mid]
    else:
        return (sorted_nums[mid - 1] + sorted_nums[mid]) / 2
